### 4.1 State Management Patterns

1. **Server State (Redis/TanStack Query)**

```typescript
// Redis cache configuration
// lib/redis/config.ts
import { Redis } from "ioredis";

export const redis = new Redis({
  host: process.env.REDIS_HOST,
  port: parseInt(process.env.REDIS_PORT || "6379"),
  password: process.env.REDIS_PASSWORD,
  keyPrefix: "fusion:",
});

// Server-side data fetching with Redis cache
// app/api/users/route.ts
import { redis } from "@/lib/redis/config";
import { NextResponse } from "next/server";

export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const tenantId = searchParams.get("tenantId");

  // Try to get from cache
  const cacheKey = `users:${tenantId}`;
  const cachedData = await redis.get(cacheKey);

  if (cachedData) {
    return NextResponse.json(JSON.parse(cachedData));
  }

  // Fetch fresh data
  const users = await fetchUsers(tenantId);

  // Cache the response
  await redis.set(cacheKey, JSON.stringify(users), "EX", 300); // 5 minutes

  return NextResponse.json(users);
}
```

2. **Client State (TanStack Query/Zustand)**

```typescript
// store/queries/useUsers.ts
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { api } from "@/lib/api";

export function useUsers(tenantId: string) {
  const queryClient = useQueryClient();

  const usersQuery = useQuery({
    queryKey: ["users", tenantId],
    queryFn: () => api.get(`/api/users?tenantId=${tenantId}`),
    staleTime: 1000 * 60 * 5, // 5 minutes
  });

  const createUser = useMutation({
    mutationFn: (userData: NewUser) => api.post("/api/users", userData),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["users", tenantId] });
    },
  });

  return {
    users: usersQuery.data,
    isLoading: usersQuery.isLoading,
    error: usersQuery.error,
    createUser: createUser.mutate,
    isCreating: createUser.isPending,
  };
}

// store/zustand/useUIStore.ts
import { create } from "zustand";

type UIStore = {
  sidebarOpen: boolean;
  theme: "light" | "dark" | "system";
  toggleSidebar: () => void;
  setTheme: (theme: "light" | "dark" | "system") => void;
};

export const useUIStore = create<UIStore>((set) => ({
  sidebarOpen: false,
  theme: "system",
  toggleSidebar: () => set((state) => ({ sidebarOpen: !state.sidebarOpen })),
  setTheme: (theme) => set({ theme }),
}));
```

