### 4.3 Authentication Integration

1. **PingOne Authentication Flow**

```typescript
// lib/auth/pingone.ts
import { PingOneAuthClient } from "@pingidentity/pingone-js";

export const pingOneClient = new PingOneAuthClient({
  environmentId: process.env.PING_ENVIRONMENT_ID,
  clientId: process.env.PING_CLIENT_ID,
  redirectUri: `${process.env.NEXT_PUBLIC_BASE_URL}/api/auth/callback/pingone`,
});

export async function signIn() {
  return pingOneClient.authorize({
    responseType: "code",
    scope: "openid profile email",
  });
}

export async function handleCallback(code: string) {
  const tokens = await pingOneClient.token({
    grantType: "authorization_code",
    code,
    redirectUri: `${process.env.NEXT_PUBLIC_BASE_URL}/api/auth/callback/pingone`,
  });

  // Store the tokens in Redis session
  await storeSession(tokens);

  return tokens;
}
```

2. **Next.js API Route for Auth**

```typescript
// app/api/auth/[...nextauth]/route.ts
import NextAuth from "next-auth";
import PingOneProvider from "next-auth/providers/pingone";
import { redis } from "@/lib/redis/config";

const handler = NextAuth({
  providers: [
    PingOneProvider({
      clientId: process.env.PING_CLIENT_ID!,
      clientSecret: process.env.PING_CLIENT_SECRET!,
      issuer: `https://auth.pingone.com/${process.env.PING_ENVIRONMENT_ID}/as`,
    }),
  ],
  callbacks: {
    async jwt({ token, account, profile }) {
      if (account) {
        // Store session in Redis
        await redis.hmset(`session:${token.sub}`, {
          accessToken: account.access_token,
          refreshToken: account.refresh_token,
          expiresAt: account.expires_at?.toString(),
        });
        await redis.expire(`session:${token.sub}`, 3600); // 1 hour

        token.accessToken = account.access_token;
      }
      return token;
    },
    async session({ session, token }) {
      if (session.user) {
        session.accessToken = token.accessToken as string;
      }
      return session;
    },
  },
});

export { handler as GET, handler as POST };
```

