[standards/technology/nextjs/STD-TEC-NXT-003-frontend-design.md#63-monitoring-with-dynatrace-rum]

### 6.3 Monitoring with DynaTrace RUM

```typescript
// lib/monitoring/dynatrace.ts
"use client";

import { dynatrace } from "@dynatrace/browser-agent";

export function initDynatrace() {
  dynatrace({
    appId: "fusion-idaas-portal",
    environmentId: process.env.NEXT_PUBLIC_DYNATRACE_ENVIRONMENT_ID,
    allowedOrigins: [process.env.NEXT_PUBLIC_BASE_URL],
    userTracking: {
      enabled: true,
      dataCollection: {
        userSessionProperties: true,
      },
    },
  });
}

export function trackPageView(name: string) {
  dynatrace.enterAction({
    name,
    actionType: "page",
  });
}

export function trackUserAction(name: string, properties: Record<string, any>) {
  dynatrace.sendBrowserEvent({
    eventType: name,
    ...properties,
  });
}
```

